/**
 * The page footer: the copyright line and the same two links. Axes: layout (minimal, centered), density
 * (default, compact).
 */
import { type JSX } from "solid-js";
import { Block } from "../primitives/block/block";
import { Container } from "../primitives/container/container";
import { Group } from "../primitives/group/group";
import { Link } from "../primitives/link/link";
import { Text } from "../primitives/text/text";
import { NavBlock } from "../components/nav-block";
import { cn, tpl, uniqLabel } from "../utils";
import type { SiteFooterLabels } from "./site-footer.types";

export type SiteFooterProps = {
  labels: SiteFooterLabels;
  layout?: "minimal" | "centered";
  density?: "default" | "compact";
  landmarkLabel?: string;
};

export function SiteFooter({
  labels,
  layout = "minimal",
  density = "default",
  landmarkLabel,
}: SiteFooterProps) {
  return (
    <Block
      tag="footer"
      class="mt-12 border-t border-border"
      data-testid="site-footer"
      data-layout={layout}
      aria-label={landmarkLabel}
    >
      <Container
        class={cn(
          "mx-auto w-full max-w-6xl px-4",
          "flex flex-wrap items-center gap-4",
          (((density as string) === "compact") ? "py-4" : "py-6"),
          (((layout as string) === "centered") ? "flex-col text-center" : "justify-between")
        )}
        data-slot="container"
      >
        <Text size="sm" class="text-muted-foreground" data-testid="copyright">
          {labels.copyright}
        </Text>
        <NavBlock label={(landmarkLabel ? uniqLabel(tpl("{0}, {1}", labels.nav, landmarkLabel)) : labels.nav)}>
          <Group gap="4">
            <Link href="#/" variant="default">
              {labels.home}
            </Link>
            <Link href="#/pricing" variant="default">
              {labels.pricing}
            </Link>
          </Group>
        </NavBlock>
      </Container>
    </Block>
  );
}

